-- Verificacao
SELECT origin, COUNT(*) FROM chart_of_accounts
WHERE company_id = (SELECT id FROM companies WHERE legal_name ILIKE '%hotelsys%' LIMIT 1)
  AND deleted_at IS NULL
GROUP BY origin
ORDER BY origin NULLS FIRST;